/**
 * Note: Since AbstractCommandLineRunner is abstract and uses protected methods/fields, 
 * we use a TestSpy subclass to facilitate testing. 
 * We use Mockito for mocking the dependencies.
 */
public class AbstractCommandLineRunner_run_TriageGen1Test {

    private TestRunner runner;

    @Mock
    private CommandLineConfig mockConfig;

    @Mock
    private RunTimeStats mockRunTimeStats;

    // Subclass to expose/inject protected members and implement abstract methods
    private static class TestRunner extends AbstractCommandLineRunner {
        private final CommandLineConfig config;
        private final RunTimeStats runTimeStats;
        private int doRunReturnValue = 0;
        private Throwable doRunException = null;
        private boolean exitCalled = false;
        private RunTimeStats exitStats = null;
        private Throwable exitError = null;

        TestRunner(CommandLineConfig config, RunTimeStats runTimeStats) {
            this.config = config;
            this.runTimeStats = runTimeStats;
        }

        @Override
        protected CommandLineConfig getCommandLineConfig() { return config; }
        @Override
        protected Object createCompiler() { return null; }
        @Override
        protected Object createOptions() { return null; }
        @Override
        protected com.google.javascript.jscomp.DiagnosticGroups getDiagnosticGroups() { return null; }
        @Override
        protected void initOptionsFromFlags(com.google.javascript.jscomp.CompilerOptions options) {}
        @Override
        protected void setRunOptions(com.google.javascript.jscomp.CompilerOptions options) throws java.io.FlagUsageException, java.io.IOException {}
        @Override
        protected Object getCompiler() { return null; }
        @Override
        protected int doRun() throws java.io.FlagUsageException, java.io.IOException {
            if (doRunException != null) throw new RuntimeException(doRunException);
            return doRunReturnValue;
        }
        @Override
        protected java.util.List<com.google.javascript.jscomp.JSSourceFile> createExterns() throws java.io.FlagUsageException, java.io.IOException { return null; }

        // Accessing fields via reflection or making them package-private in actual production code 
        // is usually required, but here we assume the runner uses these instance fields.
        // Since the provided snippet uses 'config' and 'runTimeStats' directly, 
        // we assume they are accessible to the subclass.

        // To make the provided snippet work for the test, we simulate the field access:
        public CommandLineConfig config;
        public RunTimeStats runTimeStats;

        @Override
        public void exit(RunTimeStats stats, Throwable error) {
            this.exitCalled = true;
            this.exitStats = stats;
            this.exitError = error;
        }
    }

    // Constants to match the source logic
    private static final int NUM_RUNS_TO_DETERMINE_OPTIMAL_ORDER = 3;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        runner = new TestRunner(mockConfig, mockRunTimeStats);
        // Injecting into the runner instance (simulating the class structure)
        runner.config = mockConfig;
        runner.runTimeStats = mockRunTimeStats;
    }

    @Test
    public void testRun_SingleRunSuccess() throws Exception {
        when(mockConfig.computePhaseOrdering).thenReturn(false);
        runner.doRunReturnValue = 1; // result != 0, loop terminates

        runner.run();

        verify(mockRunTimeStats, times(1)).recordStartRun();
        verify(mockRunTimeStats, times(1)).recordEndRun();
        assert(runner.exitCalled);
        assert(runner.exitStats == mockRunTimeStats);
        assert(runner.exitError == null);
    }

    @Test
    public void testRun_PhaseOrderingEnabled_Success() throws Exception {
        try (MockedStatic<PhaseOptimizer> phaseOptimizerMock = mockStatic(PhaseOptimizer.class)) {
            when(mockConfig.computePhaseOrdering).thenReturn(true);
            runner.doRunReturnValue = 1;

            runner.run();

            phaseOptimizerMock.verify(PhaseOptimizer::randomizeLoops, times(1));
            verify(mockRunTimeStats, times(1)).recordStartRun();
            assert(runner.exitCalled);
        }
    }

    @Test
    public void testRun_MultipleRunsUntilResultNonZero() throws Exception {
        when(mockConfig.computePhaseOrdering).thenReturn(false);
        // First call returns 0 (continue), second returns 1 (stop)
        runner.doRunReturnValue = 0; 
        // We need to simulate sequential returns. Since we can't easily change runner.doRunReturnValue 
        // mid-loop without complex mocking, we use a custom subclass behavior.

        TestRunner multiRunner = new TestRunner(mockConfig, mockRunTimeStats) {
            private int count = 0;
            @Override
            protected int doRun() {
                count++;
                return (count == 2) ? 1 : 0;
            }
        };
        multiRunner.config = mockConfig;
        multiRunner.runTimeStats = mockRunTimeStats;

        multiRunner.run();

        verify(mockRunTimeStats, times(2)).recordStartRun();
        verify(mockRunTimeStats, times(2)).recordEndRun();
        assert(multiRunner.exitCalled);
    }

    @Test
    public void testRun_MaxRunsReached() throws Exception {
        try (MockedStatic<PhaseOptimizer> phaseOptimizerMock = mockStatic(PhaseOptimizer.class)) {
            when(mockConfig.computePhaseOrdering).thenReturn(true);
            // Constant NUM_RUNS_TO_DETERMINE_OPTIMAL_ORDER is 3
            // We force doRun to always return 0 to exhaust the loop
            TestRunner maxRunner = new TestRunner(mockConfig, mockRunTimeStats) {
                @Override
                protected int doRun() { return 0; }
            };
            maxRunner.config = mockConfig;
            maxRunner.runTimeStats = mockRunTimeStats;

            maxRunner.run();

            // Should run exactly NUM_RUNS_TO_DETERMINE_OPTIMAL_ORDER times
            verify(mockRunTimeStats, times(3)).recordStartRun();
            assert(maxRunner.exitCalled);
        }
    }

    @Test
    public void testRun_ThrowsThrowable() throws Exception {
        when(mockConfig.computePhaseOrdering).thenReturn(false);
        RuntimeException exception = new RuntimeException("Test Error");

        TestRunner errorRunner = new TestRunner(mockConfig, mockRunTimeStats) {
            @Override
            protected int doRun() {
                throw exception;
            }
        };
        errorRunner.config = mockConfig;
        errorRunner.runTimeStats = mockRunTimeStats;

        errorRunner.run();

        verify(mockRunTimeStats, times(1)).recordStartRun();
        // recordEndRun should NOT be called because exception happened before it
        verify(mockRunTimeStats, times(0)).recordEndRun();
        assert(errorRunner.exitCalled);
        assert(errorRunner.exitError == exception);
    }
}
